    monotonic = part_info->part_expr->get_monotonicity_info();
    if (monotonic != MONOTONIC_INCREASING_NOT_NULL &&
        monotonic != MONOTONIC_STRICT_INCREASING_NOT_NULL) {
      /* F(col) can not return NULL, return index with lowest value */
      return 0;
